-- Northern Gun Two: Huntsman's Choice and Streetwolf armored clothing, the EB-20 backpack and five Ride Armors.
-- 28 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~296-northern-gun-2-armor-a.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
--
-- Rifts World Book 34: Northern Gun Two, printed pp.39-47 (row 1 of the
-- northern-gun-2 plan, 2026-11-16). Text layer, page_offset 1. Every M.D.C.,
-- weight, cost and mobility figure was read off a 110 dpi render of cache pages
-- p040-p048, not the text cache.
--
-- Counted off the page: the Huntsman's Choice line prints 8 priced lines
-- (gloves, mittens & heavy gloves, track boots, SH-150, AH-240, MH-500, MH-550,
-- Ultra-300) and the Streetwolf line 14 (pp.42-43), 22 in all. The survey's
-- figure of 6 undercounted them. Plus the EB-20 backpack and five Ride Armors:
-- 28 rows.
--
-- Not rows: the insignia and custom-color add-ons and the five helmet upgrades
-- are options on other items (carried in cost_note); the shared Ride Armor
-- helmet features (p.44) are folded into each Ride Armor's description.
-- mdc is the main body; locations, mobility penalties and street-legal notes
-- are in the description, which the catalog has no columns for.
--
-- Page oddities, kept as printed:
-- - RA15 Cannonball (p.46) prints no Cost line; cost is NULL and cost_note says so.
-- - The Viper's heading reads "NG R33"; its text says RA33, which the name uses.
-- - Streetwolf "Tank" Pants print 5 pounds (11 kg); weight_lbs stores the 5.
-- - The head cam upgrade costs 2,500 under the Ultra-300 (p.41) and 3,500 under
--   the Ride Armor helmet (p.44); each row carries its own page's figure.
-- Not the same items, left alone: the six NG "Hunter" clothing rows (Dinosaur
-- Swamp) and mdc-armored-trench-coat (Australia).

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('ng-huntsmans-choice-gloves', 'NG Huntsman''s Choice Armored Gloves', 'rifts', 'armor', NULL, 800, 'Good availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 2, 'Armored gloves made to complete a Huntsman''s Choice jumpsuit or fatigues, from light driving gloves to full gloves. A magnetic lip locks them to the sleeve cuffs so dust, water and bugs stay out. Sold in the same colors and patterns as the clothing.', 'Rifts World Book 34: Northern Gun Two p.40', NULL),
  ('ng-huntsmans-choice-heavy-gloves', 'NG Huntsman''s Choice Mittens & Heavy Gloves', 'rifts', 'armor', NULL, 1000, 'Fair availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 4, 'Heavier armored gloves and mittens for the Huntsman''s Choice line, warm enough for arctic work. Same magnetic cuff seal as the lighter gloves.', 'Rifts World Book 34: Northern Gun Two p.40', NULL),
  ('ng-huntsmans-choice-track-boots', 'NG Huntsman''s Choice Track Boots', 'rifts', 'armor', NULL, 1200, 'Good availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 6, 'M.D.C. boots for the Huntsman''s Choice line with extra plating at toe and heel (sometimes the upper too) and a magnetic lip that seals to the trouser cuff. Tread patterns are a choice; some militias order their own insignia tread. Usually black or dark brown.', 'Rifts World Book 34: Northern Gun Two p.40', NULL),
  ('ng-sh-150-huntsmans-choice-jumpsuit', 'NG SH-150 Standard S.D.C. Huntsman''s Choice Jumpsuit or Fatigues', 'rifts', 'armor', NULL, 375, 'Excellent availability. Insignia patch 10-40 credits each; custom colors or patterns 200-2,500 credits.', NULL, 0, NULL, NULL, NULL, 14, 35, NULL, 'The basic S.D.C. version of NG''s uniform clothing: a one-piece jumpsuit, or fatigues sold as a shirt-and-pants set, wind and water resistant, with a dozen magnetic-closure pockets and padded knees and elbows. A.R. 14, +2 with a helmet. No movement penalty. Not environmental: the cuffs seal out dirt and insects but not gas or contaminants.', 'Rifts World Book 34: Northern Gun Two p.39-40', NULL),
  ('ng-ah-240-huntsmans-choice-jumpsuit', 'NG AH-240 S.D.C. Huntsman''s Choice Jumpsuit or Fatigues', 'rifts', 'armor', NULL, 750, 'Good availability.', NULL, 0, NULL, NULL, NULL, 16, 60, NULL, 'Huntsman''s Choice S.D.C. jumpsuit or fatigues with light ceramic plates over chest and back, polycarbonate plates and padding on the front and thighs, and knee and elbow padding. A.R. 16, +2 with a helmet. No movement penalty. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.41', NULL),
  ('ng-mh-500-huntsmans-choice-jumpsuit', 'NG MH-500 Armored Huntsman''s Choice Jumpsuit or Fatigues', 'rifts', 'armor', NULL, 1500, 'Good availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 6, 'Huntsman''s Choice jumpsuit or fatigues woven wholly from Mega-Damage micro-fiber cloth and padding, with no plates. No movement penalty. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.41', NULL),
  ('ng-mh-550-huntsmans-choice-jumpsuit', 'NG MH-550 Armored Huntsman''s Choice Jumpsuit or Fatigues', 'rifts', 'armor', NULL, 3500, 'Fair availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 11, 'The MH-500 with light M.D.C. ceramic plates added over chest and back, plus Mega-Damage padding with plastic strips over the front and thighs and guards at knee and elbow. No movement penalty. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.41', NULL),
  ('ng-ultra-300-huntsmans-choice-jumpsuit', 'NG Ultra-300 Armored Huntsman''s Choice Jumpsuit or Fatigues', 'rifts', 'armor', 7, 7500, 'Good availability. Helmet upgrades: language translator 10,000; helmet lamp 1,200; head cam 2,500; gas mask 1,000; oxygen connector and 60-minute tank 4,500.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 25, 'Effectively light body armor in jumpsuit form, comparable to old Plastic Man armor but more flexible: the MH-550''s plating plus outer plates on neck, shoulders, chest, upper back, forearms and shins, heavier ceramic plates hidden over the thighs, and knee and elbow guards. Main body 25 M.D.C.; helmet 35; each arm 10; each leg 14. Good to excellent mobility, -2% movement penalty. Includes the Ultra-300 helmet, built like the Ride Armor helmet: a polarized visor that darkens and lightens with the light, a HUD on the visor, a 5 mile (8 km) radio and an outside speaker. It clips to the collar to keep out dust and insects, but there is no air seal or air supply, so gas, disease and radiation still get in.', 'Rifts World Book 34: Northern Gun Two p.41', NULL),
  ('ng-streetwolf-racing-jacket', 'NG Streetwolf Light M.D.C. Racing Jacket', 'rifts', 'armor', 2, 1900, 'Add 900 credits for imitation leather. Fair to good availability at NG outlets, poor elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 6, 'A light Streetwolf jacket of M.D.C. micro-fiber, cut for riders. Non-environmental, street legal almost everywhere.', 'Rifts World Book 34: Northern Gun Two p.42', NULL),
  ('ng-streetwolf-aviator-flight-jacket', 'NG Streetwolf Armored M.D.C. Aviator''s Flight Jacket', 'rifts', 'armor', 3, 3600, 'Fair to good availability at NG outlets, poor elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 10, 'A modern waist-length flight jacket in faux leather or cloth, favored by aircraft and robot pilots: pockets on shoulders, forearms and chest but none at the waist. M.D.C. fabric with light padding. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.42', NULL),
  ('ng-streetwolf-bomber-jacket', 'NG Streetwolf Armored M.D.C. Aviator''s Bomber Jacket', 'rifts', 'armor', 4.5, 4200, 'Add 30-50% for oversized or custom coats for larger than human D-Bees. Fair to good availability at NG outlets, poor elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 12, 'A classic WWII-style leather bomber jacket ending at the belt, with M.D.C. padding or thin polycarbonate plates hidden in the lining at the neck-to-shoulder area, shoulders, forearms, elbows, chest and back. A favorite of Techno-Wizards and pilots. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.42', NULL),
  ('ng-streetwolf-biker-jacket', 'NG Streetwolf Armored M.D.C. Biker''s Jacket', 'rifts', 'armor', 5.6, 5500, 'Add 30-50% for oversized or custom coats for larger than human D-Bees. Fair to good availability at NG outlets, poor elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 15, 'Motorcycle jacket in classic and modern cuts, padded and plated inside at shoulders, forearms, elbows, chest and back, with visible ceramic or metal plates, studs or strips over shoulders and forearms and elbow guards. Popular with City Rats, bikers and gangs. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.42', NULL),
  ('ng-streetwolf-fireman-long-coat', 'NG Streetwolf Armored M.D.C. Fireman''s Long Coat', 'rifts', 'armor', 8, 9500, 'Add 30-50% for oversized or custom coats for larger than human D-Bees. Fair to good availability at NG outlets, poor elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 28, 'The Sharp Duster''s protection in a firefighter''s coat: tall collar, bright yellow or red, with colored LED strips on collar, arms and legs so crews can be spotted. M.D.C. fabric, padding and polycarbonate plates in the lining. Sold to fire crews and first responders. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.42', NULL),
  ('ng-streetwolf-sharp-duster', 'NG Streetwolf Armored M.D.C. Sharp Duster/Long Coat', 'rifts', 'armor', 8, 9500, 'Custom colors or patterns add 3,000-6,000 credits; add 30-50% for oversized or custom coats for larger than human D-Bees. Fair to good availability at NG outlets, poor elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 28, 'An ankle-length cowboy duster, a more stylish imitation of the Branaghan Duster, in six stock colors. M.D.C. fabric, padding and polycarbonate plates run through the lining. A staple of the New West. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.42', NULL),
  ('ng-streetwolf-executive-trench-coat', 'NG Streetwolf Armored M.D.C. Executive Trench Coat', 'rifts', 'armor', 6, 10500, 'Faux leather adds 3,500 credits; add 30-50% for oversized or custom coats for larger than human D-Bees. Fair to good availability at NG outlets, poor elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 26, 'A tailored knee-length trench coat, shorter than the Sharp Duster, in seven colors or faux leather, with men''s and women''s cuts. M.D.C. fabric, padding and polycarbonate strips hidden in the lining. Favored by executives, salesmen, Black Marketeers and spies. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.42-43', NULL),
  ('ng-streetwolf-combat-trench-coat', 'NG Streetwolf Armored M.D.C. Combat Trench Coat or Long Coat', 'rifts', 'armor', 10, 16500, 'Faux leather or custom colors add 3,500-7,000 credits; add 30-50% for oversized or custom coats for larger than human D-Bees. Fair to good availability at NG outlets, poor elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 36, 'The Executive Trench Coat or Sharp Duster cut with denser plastic and ceramic plates in the lining and visible outer plating on shoulders, collar, arms and elbows. Ten colors, men''s and women''s cuts. Popular with Juicers, Crazies, security and criminals. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.43', NULL),
  ('ng-streetwolf-tank-trench-coat', 'NG Streetwolf Armored M.D.C. "Tank" Trench Coat or Long Coat', 'rifts', 'armor', 20, 22500, 'Faux leather or custom colors add 3,500-7,000 credits; add 50-100% for oversized or custom coats for larger than human D-Bees. Fair to good availability at NG outlets, poor elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 50, 'The heaviest Streetwolf coat, in trench or duster cut: thicker plates in the lining and conspicuous outer plating on the upper body, shoulders and arms. Extra-large sizes for Juicers, borgs and big D-Bees. A wearer with a natural P.S. under 24 is -2 on initiative, -1 on all combat moves, leaps half as far, loses 10% speed and tires 20% faster. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.43', NULL),
  ('ng-streetwolf-light-business-suit-coat', 'NG Streetwolf Light Executive M.D.C. Business Suit Coat', 'rifts', 'armor', 2, 2100, 'Faux leather adds 1,200 credits. Fair to good availability at NG outlets, poor elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 6, 'A lightly armored suit jacket of M.D.C. fabric in a few basic business styles. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.43', NULL),
  ('ng-streetwolf-armored-business-suit-coat', 'NG Streetwolf Armored Executive M.D.C. Business Suit Coat', 'rifts', 'armor', 3.5, 3500, 'Faux leather adds 1,000 credits. Fair to good availability at NG outlets, poor elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 8, 'A heavier armored suit jacket of M.D.C. fabric for executives. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.43', NULL),
  ('ng-streetwolf-executive-trousers', 'NG Streetwolf Executive M.D.C. Trousers/Slacks', 'rifts', 'armor', 1, 1500, 'Fair to good availability at NG outlets, poor elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 3, 'Business and formal slacks of M.D.C. fabric with light padding at hips, knees and shins. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.43', NULL),
  ('ng-streetwolf-combat-pants', 'NG Streetwolf M.D.C. Combat Pants', 'rifts', 'armor', 2, 3000, 'Fair to good availability at NG outlets, poor elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 8, 'Cargo pants, fatigues or jeans of M.D.C. fabric with padding and hidden polycarbonate plates over hips, thighs, knees and shins. Non-environmental.', 'Rifts World Book 34: Northern Gun Two p.43', NULL),
  ('ng-streetwolf-tank-pants', 'NG Streetwolf M.D.C. "Tank" Pants', 'rifts', 'armor', 5, 6500, 'Fair to good availability at NG outlets, poor elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 12, 'Combat Pants with obvious ceramic plates added outside over thighs, knees and shins; cargo, fatigue or flight-pant styles. Non-environmental. The book prints the weight as 5 pounds (11 kg); the pounds figure is stored.', 'Rifts World Book 34: Northern Gun Two p.43', NULL),
  ('ng-eb-20-hunter-backpack', 'NG EB-20 Hunter Environmental Backpack', 'rifts', 'gear', 6, 8500, 'Good availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 25, 'A hard M.D.C. ceramic box pack whose interior is climate controlled to keep food and specimens from spoiling, divided by padded fabric pockets and sleeves. Opens by a round screw lid or by lifting the whole top. Modular connectors clip it to NG body armor, power armor, robots or hovercycles; it also has fold-away shoulder straps and a carry handle. A one liter thermos (2 M.D.C.) clips on top and side straps hold small tools. Weight is empty.', 'Rifts World Book 34: Northern Gun Two p.43-44', NULL),
  ('ng-ra5-arrow-ride-armor', 'NG RA5 Arrow Ride Armor', 'rifts', 'armor', 9, 12500, 'Good availability. Helmet upgrades: language translator 10,000; helmet lamp 1,200; head cam 3,500; gas mask 1,000; oxygen connector and 60-minute tank 4,500.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 30, 'The sleekest hovercycle Ride Armor, with an arrowhead-shaped helmet; built for racers and trick riders. An M.D.C. micro-fiber jumpsuit with thin plates on forearms, elbows, knees, legs and boot tops, flexible plates at the lower belly and padded, plated shoulders and chest. Main body 30 M.D.C.; head/helmet 35; each arm 14; each leg 18. Mobility excellent: -2% to Climb, Prowl, Swim, Acrobatics and similar skills. Non-environmental and street legal in most towns. Standard Ride Armor helmet: self-darkening polarized visor, visor HUD, 5 mile (8 km) radio, external speaker, and collar connectors that keep out dust and insects but give no air seal or air supply.', 'Rifts World Book 34: Northern Gun Two p.44-45', NULL),
  ('ng-ra10-bullet-ride-armor', 'NG RA10 Bullet Ride Armor', 'rifts', 'armor', 10, 14500, 'Good availability. Helmet upgrades: language translator 10,000; helmet lamp 1,200; head cam 3,500; gas mask 1,000; oxygen connector and 60-minute tank 4,500.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 36, 'Aerodynamic Ride Armor that puts its heaviest plating on the head, shoulders, chest and shins, the parts exposed when leaning over a speeding bike, with light padding and hidden plates elsewhere. Many detachable pouches on belt, hips, chest and shoulders, a small compartment in the leg armor, a harness-like rim with storage and forward lights, and back mounts for a pack, air tanks or jet pack. Main body 36 M.D.C. with +10 at the chest; head/helmet 35; each arm 10 with +6 at its shoulder; each leg 22. Mobility excellent: -4% to Climb, Prowl, Swim, Acrobatics and similar skills. Non-environmental, street legal in most towns. Standard Ride Armor helmet: self-darkening polarized visor, visor HUD, 5 mile (8 km) radio, external speaker, and collar connectors that keep out dust and insects but give no air seal or air supply.', 'Rifts World Book 34: Northern Gun Two p.45-46', NULL),
  ('ng-ra15-cannonball-ride-armor', 'NG RA15 Cannonball Ride Armor', 'rifts', 'armor', 13, NULL, 'No price is printed: the stat block on p.46 ends after M.D.C. by Location. Helmet upgrades: language translator 10,000; helmet lamp 1,200; head cam 3,500; gas mask 1,000; oxygen connector and 60-minute tank 4,500.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 42, 'The second heaviest Ride Armor, made to let a rider survive a high-speed spill: heavy plating and padding on head, shoulders, chest, belly and shins, hidden extra armor at hips and thighs, and a wide neck collar. Oversized shoulder pads each hide a compartment for E-Clips, flares or grenades; a detachable flashlight rides the left shoulder; many pouches, hooks and straps; back mounts for a pack, air tanks or jet pack. Main body 42 M.D.C. with +10 at chest and neck; head/helmet 35; each arm 15 with +15 at its shoulder; each leg 27. Mobility good: -6% to Climb, Prowl, Swim, Acrobatics and similar skills. Non-environmental; street legal with the helmet off. Standard Ride Armor helmet: self-darkening polarized visor, visor HUD, 5 mile (8 km) radio, external speaker, and collar connectors that keep out dust and insects but give no air seal or air supply.', 'Rifts World Book 34: Northern Gun Two p.46', NULL),
  ('ng-ra20-roadrunner-ride-armor', 'NG RA20 Roadrunner Ride Armor', 'rifts', 'armor', 9, 15500, 'Good availability. Helmet upgrades: language translator 10,000; helmet lamp 1,200; head cam 3,500; gas mask 1,000; oxygen connector and 60-minute tank 4,500.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 32, 'A common, comfortable Ride Armor: solid protection for the torso, neck and shoulders, decent arm armor, and only knee pads plus light padding and plates in the trouser lining for the legs. Plenty of straps and clips for travel gear; uses the Bullet''s helmet. Main body 32 M.D.C. with +10 at chest and neck; head/helmet 35; each arm 20; each leg 11. Mobility excellent: -2% to Climb, Prowl, Swim, Acrobatics and similar skills. Non-environmental, street legal in most towns. Standard Ride Armor helmet: self-darkening polarized visor, visor HUD, 5 mile (8 km) radio, external speaker, and collar connectors that keep out dust and insects but give no air seal or air supply.', 'Rifts World Book 34: Northern Gun Two p.46-47', NULL),
  ('ng-ra33-viper-ride-armor', 'NG RA33 Viper Ride Armor', 'rifts', 'armor', 16, 28500, 'Good availability. Helmet upgrades: language translator 10,000; helmet lamp 1,200; head cam 3,500; gas mask 1,000; oxygen connector and 60-minute tank 4,500.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 60, 'The heaviest Ride Armor, often taken for environmental armor though it is not: plated everywhere, even the backs of the hands, except the belly, waist and inner thighs, which have only padding (a Called Shot at -5 to strike, -10 when the rider is moving over 25 mph). The helmet trails ribbon tassels. Clips and hooks for pouches; back mounts for a pack, ammo drum, air tanks or jet pack. Illegal on the streets of about half of North America''s cities unless the helmet and the arm and thigh plates come off. Main body 60 M.D.C.; head/helmet 50; each arm 25; each leg 38. Mobility fair to good: -10% to Climb, Prowl, Swim, Acrobatics and similar skills, and -2% on evasive maneuvers and stunt driving. Standard Ride Armor helmet: self-darkening polarized visor, visor HUD, 5 mile (8 km) radio, external speaker, and collar connectors that keep out dust and insects but give no air seal or air supply. The heading prints R33; the text and model series say RA33.', 'Rifts World Book 34: Northern Gun Two p.47', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 28 gear rows are in' AS assertion, count(*) AS got, 28 AS want
  FROM gear WHERE slug IN ('ng-huntsmans-choice-gloves', 'ng-huntsmans-choice-heavy-gloves', 'ng-huntsmans-choice-track-boots', 'ng-sh-150-huntsmans-choice-jumpsuit', 'ng-ah-240-huntsmans-choice-jumpsuit', 'ng-mh-500-huntsmans-choice-jumpsuit', 'ng-mh-550-huntsmans-choice-jumpsuit', 'ng-ultra-300-huntsmans-choice-jumpsuit', 'ng-streetwolf-racing-jacket', 'ng-streetwolf-aviator-flight-jacket', 'ng-streetwolf-bomber-jacket', 'ng-streetwolf-biker-jacket', 'ng-streetwolf-fireman-long-coat', 'ng-streetwolf-sharp-duster', 'ng-streetwolf-executive-trench-coat', 'ng-streetwolf-combat-trench-coat', 'ng-streetwolf-tank-trench-coat', 'ng-streetwolf-light-business-suit-coat', 'ng-streetwolf-armored-business-suit-coat', 'ng-streetwolf-executive-trousers', 'ng-streetwolf-combat-pants', 'ng-streetwolf-tank-pants', 'ng-eb-20-hunter-backpack', 'ng-ra5-arrow-ride-armor', 'ng-ra10-bullet-ride-armor', 'ng-ra15-cannonball-ride-armor', 'ng-ra20-roadrunner-ride-armor', 'ng-ra33-viper-ride-armor') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~296-northern-gun-2-armor-a.sql');
